changeSet.sql:
CREATE TABLE bng.post_intervention_red_line (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL UNIQUE
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    geom geometry(MultiPolygon, 27700) NOT NULL
);

CREATE INDEX idx_post_intervention_red_line_geom
    ON bng.post_intervention_red_line USING GIST (geom);

CREATE TABLE bng.post_intervention_habitats (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    ref text,
    geom geometry(MultiPolygon, 27700) NOT NULL
);

CREATE INDEX idx_post_intervention_habitats_project_id
    ON bng.post_intervention_habitats (project_id);

CREATE INDEX idx_post_intervention_habitats_geom
    ON bng.post_intervention_habitats USING GIST (geom);

CREATE TABLE bng.post_intervention_hedgerows (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    ref text,
    geom geometry(MultiLineString, 27700) NOT NULL
);

CREATE INDEX idx_post_intervention_hedgerows_project_id
    ON bng.post_intervention_hedgerows (project_id);

CREATE INDEX idx_post_intervention_hedgerows_geom
    ON bng.post_intervention_hedgerows USING GIST (geom);

CREATE TABLE bng.post_intervention_watercourses (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    ref text,
    geom geometry(MultiLineString, 27700) NOT NULL
);

CREATE INDEX idx_post_intervention_watercourses_project_id
    ON bng.post_intervention_watercourses (project_id);

CREATE INDEX idx_post_intervention_watercourses_geom
    ON bng.post_intervention_watercourses USING GIST (geom);
